from summarize import summarize


def test_summarize_basic():
    """Test basic functionality with valid data."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': 50}
    ]
    result = summarize(rows)
    assert result == {'North': 150.0, 'South': 200.0}


def test_summarize_with_string_revenue():
    """Test with revenue as string."""
    rows = [
        {'region': 'East', 'revenue': '150.5'},
        {'region': 'West', 'revenue': '200'}
    ]
    result = summarize(rows)
    assert result == {'East': 150.5, 'West': 200.0}


def test_summarize_missing_revenue():
    """Test that rows with missing revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South'},  # missing revenue
        {'region': 'East', 'revenue': 50}
    ]
    result = summarize(rows)
    assert result == {'North': 100.0, 'East': 50.0}


def test_summarize_unparseable_revenue():
    """Test that rows with unparseable revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 'invalid'},
        {'region': 'East', 'revenue': None},
        {'region': 'West', 'revenue': '150'}
    ]
    result = summarize(rows)
    assert result == {'North': 100.0, 'West': 150.0}


def test_summarize_missing_region():
    """Test that rows with missing region are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'revenue': 50},  # missing region
        {'region': 'South', 'revenue': 200}
    ]
    result = summarize(rows)
    assert result == {'North': 100.0, 'South': 200.0}


def test_summarize_empty_list():
    """Test with empty list."""
    rows = []
    result = summarize(rows)
    assert result == {}


def test_summarize_all_invalid():
    """Test when all rows have invalid data."""
    rows = [
        {'region': 'North', 'revenue': 'invalid'},
        {'region': None, 'revenue': 100}
    ]
    result = summarize(rows)
    assert result == {}


def test_summarize_float_revenue():
    """Test with float revenue values."""
    rows = [
        {'region': 'A', 'revenue': 10.5},
        {'region': 'A', 'revenue': 20.7}
    ]
    result = summarize(rows)
    assert result == {'A': 31.2}

